.modal {
  --modal-margin: 1.25rem;
  --modal-max-width: 50rem;
  visibility: hidden;
  z-index: -1;
  opacity: 0;
  width: 100%;
  height: 100%;
  display: block;
  position: fixed;
  top: 0;
  left: 0;
  overflow: hidden auto;
}

.modal__overlay {
  background-color: #0000004d;
  width: 100vw;
  height: 100vh;
  position: fixed;
  top: 0;
  left: 0;
}

.modal.is-open {
  opacity: 1;
  visibility: visible;
  z-index: 110;
  transition: opacity .5s;
}

.modal.is-open .modal__inner {
  transition: transform .5s;
  transform: translateY(0);
}

.modal__inner {
  width: 100%;
  max-width: var(--modal-max-width);
  height: calc(100% - var(--modal-margin) * 2);
  padding: 0 var(--modal-margin);
  margin: var(--modal-margin) auto;
  pointer-events: none;
  align-items: center;
  display: flex;
  position: relative;
  transform: translateY(-3.125rem);
}

.modal__content {
  pointer-events: auto;
  background-color: #fff;
  border-radius: .5rem;
  width: 100%;
  max-height: 100%;
  padding: 2.5rem;
  position: relative;
  overflow-y: auto;
}

@media (width >= 640px) {
  .modal__content {
    padding-top: 3.125rem;
  }
}

.modal__close {
  cursor: pointer;
  line-height: 0;
  display: inline-block;
  position: absolute;
  top: .75rem;
  right: .75rem;
}

.modal__close:hover svg {
  transform: scale(1.1);
}

.modal__close svg {
  fill: #ff6015;
